add('8.NS.1','Rational and irrational numbers',['fraction-classification','root-classification'],(t,f)=>{const n=t.int(2,18),d=t.int(2,12),square=n*n,irr=square+1,right=f==='fraction-classification'?'Rational':'Irrational';return t.choice('Classify '+(f==='fraction-classification'?n+'/'+d:'√'+irr)+'.',right,[right==='Rational'?'Irrational':'Rational','Both rational and irrational','Neither rational nor irrational'],f==='fraction-classification'?'A ratio of integers with nonzero denominator is rational.':'The radicand is not a perfect square; its square root is irrational.',{kind:'number-class',fraction:f==='fraction-classification',n:f==='fraction-classification'?n:irr,d});});
