add('8.EE.1','Integer exponent properties',['multiply-powers','divide-powers'],(t,f)=>{const base=t.int(2,9),a=t.int(-3,5),b=t.int(-3,5),e=f==='multiply-powers'?a+b:a-b;return t.choice('Write '+base+'^('+a+') '+(f==='multiply-powers'?'×':'÷')+' '+base+'^('+b+') as one power of '+base+'.',base+'^('+e+')',[base+'^('+(e+1)+')',base+'^('+(e-1)+')',base+'^('+(e+2)+')'],'For a common nonzero base, '+(f==='multiply-powers'?'add':'subtract')+' the exponents.',{kind:'exponent',base,a,b,op:f});});
add('8.EE.2','Square and cube roots',['square-root','cube-root'],(t,f)=>{const n=t.int(2,18),cube=f==='cube-root';return t.number(cube?'Solve x³ = '+n**3+'.':'Find the nonnegative solution of x² = '+n*n+'.',n,cube?'The real cube root is the number whose cube gives the right side.':'A positive square has positive and negative square roots; the prompt asks for the nonnegative one.',{kind:cube?'cube-root':'square-root',value:cube?n**3:n*n});},'Use root symbols, identify both solutions of x² = p, evaluate perfect square/cube roots, and explain why √2 cannot be written as a ratio of integers.');
add('8.EE.3','Compare powers-of-ten quantities',['larger-quantity','smaller-quantity'],(t,f)=>{const c=t.int(1,9),e=t.int(2,8),gap=t.int(1,5),more=f==='larger-quantity';return t.number('How many times '+(more?'as large is '+c+' × 10^'+(e+gap)+' as '+c+' × 10^'+e:'does '+c+' × 10^'+e+' fit into '+c+' × 10^'+(e+gap))+'?',10**gap,'The matching coefficients cancel; subtract exponents to find the factor.',{kind:'power-ratio',c,e,gap});});
function scientific(coefficient,exponent){while(Math.abs(coefficient)>=10){coefficient/=10;exponent++;}while(coefficient!==0&&Math.abs(coefficient)<1){coefficient*=10;exponent--;}return clean(coefficient)+' × 10^'+exponent;}
add('8.EE.4','Scientific notation operations',['scientific-product','scientific-sum'],(t,f)=>{const a=t.int(1,9),b=t.int(1,9),e=t.int(-5,7),d=t.int(-4,6),product=f==='scientific-product',coefficient=product?a*b:a+b,exponent=product?e+d:e;return t.choice('Compute ('+a+' × 10^'+e+') '+(product?'× ('+b+' × 10^'+d+')':'+ ('+b+' × 10^'+e+')')+'. Write normalized scientific notation.',scientific(coefficient,exponent),[scientific(coefficient,exponent+1),scientific(coefficient,exponent-1),scientific(coefficient+1,exponent)],'Combine coefficients and powers, then normalize the coefficient to at least 1 and below 10.',{kind:'scientific',a,b,e,d,product});});
add('8.EE.5','Proportional graphs and slope',['graph-rate','compare-rates'],(t,f)=>{const a=t.int(2,9),b=a+t.int(1,5),points=[[0,0],[1,a],[2,a*2],[3,a*3]];return f==='graph-rate'?t.number('The graph shows distance versus time. What is its unit rate?',a,'Divide change in distance by change in time.',{kind:'slope',points},{kind:'coordinates',points,segments:[[0,3]],xLabel:'Time',yLabel:'Distance'}):t.choice('Graph A is shown. Rule B is y = '+b+'x. Which has the greater unit rate?','Rule B',['Graph A','Their unit rates are equal','Neither has a unit rate'],'Graph A has slope '+a+'; Rule B has slope '+b+'.',{kind:'text',right:'Rule B'},{kind:'coordinates',points,segments:[[0,3]]});});
